import React from 'react';
import { BrowserRouter, Navigate, Route, Routes } from 'react-router-dom';
import Layout from './components/Layout';
import PrivateRoute from './components/PrivateRoute';
import AdminDashboard from './pages/AdminDashboard';
import Analytics from './pages/Analytics';
import Assessment from './pages/Assessment';
import Dashboard from './pages/Dashboard';
import ForgotPassword from './pages/ForgotPassword';
import Login from './pages/Login';
import Profile from './pages/Profile';
import Recommendations from './pages/Recommendations';
import Register from './pages/Register';

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />
        <Route path="/forgot-password" element={<ForgotPassword />} />
        <Route path="/" element={<Navigate to="/dashboard" replace />} />
        <Route
          path="/dashboard"
          element={<PrivateRoute><Layout><Dashboard /></Layout></PrivateRoute>}
        />
        <Route
          path="/assessment"
          element={<PrivateRoute><Layout><Assessment /></Layout></PrivateRoute>}
        />
        <Route
          path="/analytics"
          element={<PrivateRoute><Layout><Analytics /></Layout></PrivateRoute>}
        />
        <Route
          path="/recommendations"
          element={<PrivateRoute><Layout><Recommendations /></Layout></PrivateRoute>}
        />
        <Route
          path="/profile"
          element={<PrivateRoute><Layout><Profile /></Layout></PrivateRoute>}
        />
        <Route
          path="/admin"
          element={<PrivateRoute adminOnly><Layout><AdminDashboard /></Layout></PrivateRoute>}
        />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
